// NewQueryPayload builds a analytics service query endpoint payload.
func NewQueryPayload(body *QueryRequestBody, sessionToken *string, projectSlugInput *string) *analytics.QueryPayload {
	v := &analytics.QueryPayload{
		Dataset: *body.Dataset,
		From:    *body.From,
		To:      *body.To,
		Grain:   body.Grain,
		Limit:   body.Limit,
	}
	if body.Ungrouped != nil {
		v.Ungrouped = *body.Ungrouped
	}
	if body.Dimensions != nil {
		v.Dimensions = make([]string, len(body.Dimensions))
		for i, val := range body.Dimensions {
			v.Dimensions[i] = val
		}
	}
	if body.Measures != nil {
		v.Measures = make([]*analytics.AnalyticsMeasure, len(body.Measures))
		for i, val := range body.Measures {
			if val == nil {
				v.Measures[i] = nil
				continue
			}
			v.Measures[i] = unmarshalAnalyticsMeasureRequestBodyToAnalyticsAnalyticsMeasure(val)
		}
	}
	if body.Filters != nil {
		v.Filters = make([]*analytics.AnalyticsFilter, len(body.Filters))
		for i, val := range body.Filters {
			if val == nil {
				v.Filters[i] = nil
				continue
			}
			v.Filters[i] = unmarshalAnalyticsFilterRequestBodyToAnalyticsAnalyticsFilter(val)
		}
	}
	if body.OrderBy != nil {
		v.OrderBy = make([]*analytics.AnalyticsOrderBy, len(body.OrderBy))
		for i, val := range body.OrderBy {
			if val == nil {
				v.OrderBy[i] = nil
				continue
			}
			v.OrderBy[i] = unmarshalAnalyticsOrderByRequestBodyToAnalyticsAnalyticsOrderBy(val)
		}
	}
	if body.Ungrouped == nil {
		v.Ungrouped = false
	}
	v.SessionToken = sessionToken
	v.ProjectSlugInput = projectSlugInput

	return v
}

